<?php defined('VV_ROOT') || exit; $health=\VV\Operations::health($vv);$policy=$health['policy']; ?>
<div class="stats-grid"><article class="stat-card"><strong><?=e(VV_VERSION)?></strong><span><?=e(t('Version du CMS','CMS version'))?></span></article><article class="stat-card"><strong><?=e(number_format($health['storage']['bytes']/1048576,1))?> Mo</strong><span><?=e($health['storage']['partial']?t('Stockage : mesure partielle','Storage: partial scan'):t('Stockage privé','Private storage'))?></span></article><article class="stat-card"><strong><?=$health['backups']['count']?></strong><span><?=e(t('Points de restauration','Restore points'))?></span></article><article class="stat-card"><strong><?=$health['forms_notifications']['pending']?></strong><span><?=e(t('Notifications Forms en attente','Pending Forms notifications'))?></span></article></div>
<section class="panel"><h2><?=e(t('Santé de l’installation','Installation health'))?></h2><?php foreach($health['hosting']['checks'] as $check):?><div class="check-row"><span><?=e($check['label_'.lang()])?></span><span class="badge <?=$check['status']==='ok'?'green':''?>"><?=e($check['status'])?></span><small><?=e($check['value'])?></small></div><?php endforeach;?><div class="check-row"><span><?=e(t('Dernière sauvegarde','Latest backup'))?></span><strong><?=e($health['backups']['latest_at']??t('Aucune','None'))?></strong></div><div class="check-row"><span><?=e(t('Dernière maintenance','Latest maintenance'))?></span><strong><?=e($health['maintenance']['at']??t('Jamais exécutée','Never run'))?></strong></div><div class="check-row"><span><?=e(t('Erreurs dans les dernières lignes du journal','Errors in the recent log tail'))?></span><strong><?=$health['errors_in_recent_tail']?></strong></div><p class="hint"><?=e(t('Diagnostic local sans télémétrie. Le rapport exporté ne contient ni chemins privés, ni identifiants, ni messages de formulaires.','Local diagnostics without telemetry. The exported report contains no private paths, credentials or form messages.'))?></p><?=action_form('health.export',t('Exporter le diagnostic JSON','Export JSON diagnostics'),[],'secondary')?></section>
<section class="panel"><h2><?=e(t('Rétention et tâches planifiées','Retention and scheduled tasks'))?></h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="operations.save"><div class="two"><?php foreach(['logs_days'=>[t('Journaux : jours','Logs: days'),1,365],'backups_days'=>[t('Sauvegardes : jours','Backups: days'),1,365],'backups_keep'=>[t('Nombre maximal de sauvegardes','Maximum backup count'),3,30],'backup_hours'=>[t('Intervalle des sauvegardes : heures','Backup interval: hours'),1,168]] as $key=>[$label,$min,$max]):?><label><?=e($label)?><input type="number" name="<?=$key?>" min="<?=$min?>" max="<?=$max?>" value="<?=$policy[$key]?>" required></label><?php endforeach;?></div><label class="checkbox"><input type="checkbox" name="auto_backup" <?=$policy['auto_backup']?'checked':''?>><?=e(t('Créer une sauvegarde éditoriale à échéance pendant la maintenance','Create a due editorial backup during maintenance'))?></label><label class="checkbox"><input type="checkbox" name="send_notifications" <?=$policy['send_notifications']?'checked':''?>><?=e(t('Traiter les notifications Forms pendant la maintenance','Process Forms notifications during maintenance'))?></label><label><?=e(t('Mot de passe actuel','Current password'))?><input type="password" name="current_password" autocomplete="current-password" required></label><button class="button primary"><?=e(t('Enregistrer la politique','Save policy'))?></button></form><p class="hint"><?=e(t('Les deux points les plus récents sont toujours conservés. Les demandes Forms expirent selon leur propre formulaire. Les prévisualisations WordPress expirent après 1 h ; les fichiers d’export temporaires sont supprimés après téléchargement. Les sauvegardes éditoriales ne remplacent pas une copie complète du code, du stockage privé et des bases séparées de plugins comme PASS.','The two newest restore points are always retained. Forms requests expire according to their own form policy. WordPress previews expire after 1 h; temporary exports are removed after download. Editorial backups do not replace a complete copy of code, private storage and separate plugin databases such as PASS.'))?></p></section>
<section class="panel"><h2><?=e(t('Exécuter la maintenance','Run maintenance'))?></h2><p><?=e(t('Nettoie les journaux anciens, les prévisualisations expirées et les demandes Forms expirées. Applique la rétention des sauvegardes et les options ci-dessus. Aucun traitement ne part automatiquement sur une visite publique.','Cleans old logs, expired import previews and expired Forms requests. Applies backup retention and the options above. Public visits never trigger maintenance.'))?></p><pre class="log-tail">php bin/console.php maintenance:run --budget=10 --limit=3</pre><p class="hint"><?=e(t('Configurez cette commande toutes les 5 minutes dans le planificateur de votre hébergeur, avec le même stockage privé que le site. Le budget est vérifié entre tâches ; une opération disque ou un transport mail en cours peut le dépasser.','Schedule this command every 5 minutes with your host, using the same private storage as the site. The budget is checked between tasks; an active disk or mail operation may exceed it.'))?></p><?=action_form('operations.run',t('Exécuter maintenant','Run now'),[],'primary',true)?><?php if($health['maintenance']):?><?php $taskLabels=['expired_imports'=>t('Prévisualisations expirées retirées','Expired previews removed'),'log_lines_removed'=>t('Lignes de journaux retirées','Log lines removed'),'backups_removed'=>t('Anciennes sauvegardes retirées','Old backups removed'),'forms_expired'=>t('Demandes Forms expirées retirées','Expired Forms requests removed'),'backup_created'=>t('Sauvegardes créées','Backups created')];foreach($health['maintenance']['counts'] as $key=>$value):?><div class="check-row"><span><?=e($taskLabels[$key]??$key)?></span><strong><?=e($value)?></strong></div><?php endforeach;?><p class="hint"><?=e(t('Durée du dernier passage','Last run duration'))?> : <?=e($health['maintenance']['duration_ms'])?> ms</p><?php endif;?></section>
